func _init() -> void:
	var scene: PackedScene = load("res://scenes/GravityLab.tscn")
	var lab: Node2D = scene.instantiate()
	root.add_child(lab)

	var test_points := [
		[Vector2(0, 0), Vector2(300, 400)],
		[Vector2(900, -300), Vector2(-282.843, -282.843)],
		[Vector2(-900, -300), Vector2(-250, 0)],
		[Vector2(1700, 300), Vector2(0, 800)],
		[Vector2(1400, 300), Vector2(300, 400)],
		[Vector2(3000, 0), Vector2(0, 100)],
		[Vector2(0, 2000), Vector2(0, 300)],
	]

	print("--- net_gravity_at checks ---")
	var all_ok := true
	for tp in test_points:
		var pos: Vector2 = tp[0]
		var expected: Vector2 = tp[1]
		var got: Vector2 = lab.net_gravity_at(pos)
		var ok: bool = abs(got.x - expected.x) <= 0.5 and abs(got.y - expected.y) <= 0.5
		if not ok:
			all_ok = false
		print(pos, " -> got=", got, " expected=", expected, " ok=", ok)

	print("--- physics trajectory check ---")
	await process_frame
	await process_frame

	var probe: RigidBody2D = lab.get_node("Probe")
	var checkpoints := {60: null, 120: null}
	for i in range(1, 121):
		await physics_frame
		if checkpoints.has(i):
			checkpoints[i] = [probe.global_position, probe.linear_velocity]

	var expected_60_pos := Vector2(152.5, 203.333)
	var expected_60_vel := Vector2(300, 400)
	var expected_120_pos := Vector2(605.0, 806.667)
	var expected_120_vel := Vector2(600, 800)

	var r60 = checkpoints[60]
	var r120 = checkpoints[120]
	print("tick60 pos=", r60[0], " vel=", r60[1])
	print("tick120 pos=", r120[0], " vel=", r120[1])

	var pos_ok_60 = abs(r60[0].x - expected_60_pos.x) <= 25 and abs(r60[0].y - expected_60_pos.y) <= 25
	var vel_ok_60 = abs(r60[1].x - expected_60_vel.x) <= 15 and abs(r60[1].y - expected_60_vel.y) <= 15
	var pos_ok_120 = abs(r120[0].x - expected_120_pos.x) <= 25 and abs(r120[0].y - expected_120_pos.y) <= 25
	var vel_ok_120 = abs(r120[1].x - expected_120_vel.x) <= 15 and abs(r120[1].y - expected_120_vel.y) <= 15

	print("tick60 ok: pos=", pos_ok_60, " vel=", vel_ok_60)
	print("tick120 ok: pos=", pos_ok_120, " vel=", vel_ok_120)

	if not (all_ok and pos_ok_60 and vel_ok_60 and pos_ok_120 and vel_ok_120):
		print("RESULT: FAIL")
	else:
		print("RESULT: PASS")

	quit()

